/**
 * Regenerates src/chain/toolshedAbi.ts from the Foundry artifact.
 *
 *   cd ../contracts && forge build
 *   cd ../app && npx tsx src/chain/syncAbi.ts
 *
 * The generated file is committed so the app builds without the contracts
 * having been compiled first.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const artifact = resolve(import.meta.dirname, '../../../contracts/out/Toolshed.sol/Toolshed.json')
const target = resolve(import.meta.dirname, 'toolshedAbi.ts')

const { abi } = JSON.parse(readFileSync(artifact, 'utf8'))

const header = `// Generated by src/chain/syncAbi.ts from contracts/out/Toolshed.sol/Toolshed.json.
// Do not edit by hand; re-run \`npx tsx src/chain/syncAbi.ts\` after changing the contract.
`

writeFileSync(target, `${header}export const toolshedAbi = ${JSON.stringify(abi, null, 2)} as const\n`)
console.log(`wrote ${target} (${abi.length} entries)`)
